import pandas as pd

def clean_column_names(df: pd.DataFrame):
    original_columns = df.columns.tolist()
    cleaned_columns = []

    for i, col in enumerate(original_columns):
        if pd.isna(col) or col == "":
            cleaned_columns.append(f"column_{i}")
        else:
            cleaned_columns.append(str(col))

    return cleaned_columns, original_columns

import pandas as pd

    def __convert_index_to_uid(
        self, index: int | list[int], axis: typing.Literal["row", "column"] = "row"
    ):
        if isinstance(index, int):
            index = [index]
        lookup = self.get_lookup()
        if axis == "row":
            uids = [lookup.loc[lookup["row_index"] == id].uid.values[0] for id in index]
        elif axis == "column":
            uids = [
                lookup.loc[lookup["column_index"] == id].uid.values[0] for id in index
            ]
        else:
            raise ValueError('The axis must be either "row" or "column".')
        return uids

    def __convert_index_to_bodyid(self, index, axis="row"):
        if isinstance(index, int):
            index = [index]
        lookup = self.get_lookup()
        if axis == "row":
            body_ids = [
                lookup.loc[lookup["row_index"] == id].body_id.values[0] for id in index
            ]
        elif axis == "column":
            body_ids = [
                lookup.loc[lookup["column_index"] == id].body_id.values[0]
                for id in index
            ]
        else:
            raise ValueError('The axis must be either "row" or "column".')
        return body_ids

    def __get_uids_from_bodyids(self, body_ids: list[BodyId] | list[int]) -> list[UID]:
        lookup = self.get_lookup().copy()
        lookup = lookup[lookup["body_id"].isin(body_ids)]
        missing = set(body_ids) - set(lookup["body_id"].tolist())
        if len(missing) > 0:
            print(f"Warning: {len(missing)} body ids not found.")
        uids = lookup["uid"].tolist()
        return uids

import pandas as pd

    def __init__(
        self,
        matrix: sc.sparse.csr_matrix,
        lookup: pd.DataFrame,
        CR: ConnectomeReader | None = None,
    ):
        if not sc.sparse.issparse(matrix):
            matrix = sc.sparse.csr_matrix(matrix)
        if not isinstance(matrix, sc.sparse.csr_matrix):
            matrix = matrix.tocsr()
        self.matrix = matrix

        if not isinstance(lookup, pd.DataFrame):
            raise ValueError("The lookup must be a pandas dataframe.")

        lookup = lookup.copy()
        lookup["row_index"] = lookup["index"].values
        lookup["column_index"] = lookup["index"].values
        self.lookup = lookup.drop(columns="index")

        if not all(self.lookup["row_index"].isin(range(self.matrix.shape[0]))):
            raise ValueError(
                "The lookup must include row indices up to the length of the matrix."
            )
        if not all(self.lookup["column_index"].isin(range(self.matrix.shape[1]))):
            raise ValueError(
                "The lookup must include column indices up to the length of the matrix."
            )

        self.CR = CR or default_connectome_reader()

import pandas as pd

    def get_uids(
        self,
        sub_indices: Optional[list[int]] = None,
        axis: typing.Literal["row", "column"] = "row",
    ) -> list:
        if sub_indices is None:
            if axis == "row":
                self.lookup.sort_values(by="row_index", inplace=True)
            elif axis == "column":
                self.lookup.sort_values(by="column_index", inplace=True)
            return self.lookup["uid"].tolist()
        return self.__convert_index_to_uid(sub_indices, axis=axis)

    def get_row_indices(
        self,
        sub_uid: Optional[list] = None,
        allow_empty: bool = True,
        input_type: typing.Literal["uid", "body_id"] = "uid",
    ) -> list:
        if sub_uid is None:
            self.lookup.sort_values(by="row_index", inplace=True)
            return self.lookup["row_index"].tolist()

        if input_type == "body_id":
            sub_uid = self.__get_uids_from_bodyids(sub_uid)
        rows, _ = self.__convert_uid_to_index(sub_uid, allow_empty=allow_empty)
        if not allow_empty and len(rows) != len(sub_uid):
            raise ValueError("Some row body ids found only in the columns.")
        return rows

    def get_column_indices(
        self,
        sub_uid: Optional[list] = None,
        allow_empty: bool = True,
        input_type: typing.Literal["uid", "body_id"] = "uid",
    ) -> list:
        if sub_uid is None:
            self.lookup.sort_values(by="column_index", inplace=True)
            return self.lookup["column_index"].tolist()
        if input_type == "body_id":
            sub_uid = self.__get_uids_from_bodyids(sub_uid)
        _, columns = self.__convert_uid_to_index(sub_uid, allow_empty=allow_empty)
        if not allow_empty and len(columns) != len(sub_uid):
            raise ValueError("Some row body ids found only in the columns.")
        return columns

import pandas as pd

def compare_methylation_pattern_multiprocessed(motifs_scored_in_bins, bin_consensus, choices, args, num_processes=1):
    logger = logging.getLogger(__name__)
    logger.info("Starting comparison of methylation patterns")

    motifs_scored_in_contigs = motifs_scored_in_bins[motifs_scored_in_bins["n_motifs"] >= args.n_motif_contig_cutoff]
    motifs_scored_in_contigs = motifs_scored_in_contigs[["bin_contig", "motif_mod", "mean"]]
    motifs_scored_in_contigs.rename(columns={"bin_contig": "bin_compare"}, inplace=True)

    comparison_score = pd.DataFrame()
    contigs_w_no_methylation = []

    with Pool(processes=num_processes) as pool:
        results = pool.starmap(
            process_bin_contig,
            [
                (bin_contig, bin_consensus, motifs_scored_in_contigs, choices)
                for bin_contig in motifs_scored_in_contigs["bin_compare"].unique()
            ]
        )

    for result, no_methylation in results:
        if result is not None:
            comparison_score = pd.concat([comparison_score, result])
        if no_methylation is not None:
            contigs_w_no_methylation.append(no_methylation)

    return comparison_score, contigs_w_no_methylation

import pandas as pd

def sample(
    ds: Dataset, n: int | None = None, frac: float | None = None, random_state: int = 42
) -> Dataset:
    if n == 0 or frac == 0:
        return Dataset(
            pd.DataFrame(columns=ds.to_pandas().columns),
            ds.x_columns,
            ds.y_columns,
            ds.w_columns,
        )

    df = ds.to_pandas().sample(n=n, frac=frac, random_state=random_state)
    return Dataset(df, ds.x_columns, ds.y_columns, ds.w_columns)

import pandas as pd

def split(
    ds: Dataset,
    test_frac: float | None = None,
    test_n: float | None = None,
    random_state: int = 42,
) -> tuple[Dataset, Dataset]:
    if test_frac == 0 or test_n == 0:
        return ds, Dataset(
            pd.DataFrame(columns=ds.to_pandas().columns),
            ds.x_columns,
            ds.y_columns,
            ds.w_columns,
        )
    if test_frac == 1 or test_n == 1:
        return Dataset(
            pd.DataFrame(columns=ds.to_pandas().columns),
            ds.x_columns,
            ds.y_columns,
            ds.w_columns,
        ), ds

    test_size = test_frac if test_frac is not None else test_n
    train_df, test_df = train_test_split(
        ds.to_pandas(), test_size=test_size, random_state=random_state
    )
    return (
        Dataset(train_df, ds.x_columns, ds.y_columns, ds.w_columns),
        Dataset(test_df, ds.x_columns, ds.y_columns, ds.w_columns),
    )

